window.SEVN_I18N = {"en":{"nav.features":"Features","nav.devices":"Devices","nav.faq":"FAQ","nav.support":"Support","nav.privacy":"Privacy","meta.description":"Sevn is a fast, beautiful calendar for iPhone, iPad, Apple Watch and Mac with day, week, month and year views.","hero.title":"Your week at a glance.","hero.sub":"Sevn is a fast, beautiful calendar for iPhone, iPad, Apple Watch and Mac. Day, week, month and year views, with colours, emoji and templates — on top of the calendars you already use.","hero.cta":"Coming soon to the App Store","hero.note":"Works with iCloud, Google, Outlook, Exchange and every calendar in the Calendar app.","features.title":"Everything you plan, in one view","f1.t":"Week view with 7 days","f1.d":"See your whole week at once. Choose 1 to 7 days, start the week on any day and pinch to zoom the hours.","f2.t":"Day, month and year","f2.d":"Zoom out to a month with event names or a year with your busy days, and tap to jump right in.","f3.t":"Drag, copy & paste","f3.d":"Move events by dragging, change their length, copy them to another day or duplicate them in one tap.","f4.t":"Colours & emoji","f4.d":"Give events their own colour and emoji, or let rules do it automatically based on the title.","f5.t":"Templates","f5.d":"Save events you plan often and add them in one tap. Sevn also suggests details from earlier events.","f6.t":"All your calendars","f6.d":"Show, hide and group calendars into sets, create new ones, subscribe to holidays or any .ics link.","f7.t":"Synced with iCloud","f7.d":"Your settings, templates, sets, rules, colours and emoji are the same on every device.","f8.t":"Widgets & Apple Watch","f8.d":"Today, Up Next and Week widgets, plus a watch app for your day and week at a glance.","f9.t":"In your language","f9.d":"Sevn speaks more than 30 languages and follows the language of your device.","f10.t":"Weather","f10.d":"Optionally see the forecast above your days.","devices.title":"On all your Apple devices","devices.sub":"One app for iPhone, iPad, Mac and Apple Watch.","faq.title":"Questions","q1":"Does Sevn replace my calendar accounts?","a1":"No. Sevn shows and edits the calendars from the Calendar app, so everything keeps syncing through iCloud, Google, Outlook or Exchange.","q2":"Where is my data stored?","a2":"Your events stay in your own calendar accounts. Sevn's own settings sync through your private iCloud. Sevn has no servers that store your data.","q3":"Which languages are supported?","a3":"More than 30, including English, Dutch, German, French, Spanish, Italian, Portuguese, Chinese, Japanese, Korean and Arabic.","q4":"Can I add holidays?","a4":"Yes. Subscribe to public holidays for many countries with one tap, or paste any .ics link.","privacy.title":"Privacy","privacy.p1":"Sevn is built to keep your data yours.","privacy.p2":"Calendar data: Sevn reads and writes events only in the calendar accounts on your device (the Calendar app). Your events are never sent to us.","privacy.p3":"iCloud: Sevn's own settings, templates, calendar sets, rules, colours and emoji are stored in your private iCloud so they sync between your devices. We cannot access them.","privacy.p4":"Weather (optional): when you turn on weather, your approximate location is sent to Open-Meteo to get a forecast. Sevn does not store it.","privacy.p5":"No accounts, no tracking, no ads and no analytics.","privacy.p6":"Questions? Get in touch through the support page.","privacy.updated":"Last updated: 24 October 2026","support.title":"Help & Support","s1.q":"Sevn shows no events","s1.a":"Allow full calendar access: Settings › Privacy & Security › Calendars › Sevn › Full Access.","s2.q":"How do I add a Google or Outlook calendar?","s2.a":"Add the account in Settings › Apps › Calendar › Calendar Accounts (Mac: Calendar app › Add Account). Sevn shows it automatically.","s3.q":"How do I change the language?","s3.a":"Sevn follows the language of your device. On iPhone and iPad you can choose a language for Sevn only in Settings › Apps › Sevn › Language.","s4.q":"Why doesn't the app icon show today's date?","s4.a":"Only Apple's own Calendar app can change its icon by itself. Add the Sevn ‘Today’ widget to your Home Screen for a live date. On the Mac, the Dock icon shows today's date while Sevn is open.","s5.q":"Do my colours and templates sync?","s5.a":"Yes, through iCloud. Make sure you are signed in to iCloud with the same Apple Account on all your devices.","support.contact":"Still need help? Report it on GitHub.","support.contactLink":"Open an issue","footer.rights":"All rights reserved.","lang.label":"Language"}};
